const { readFileSync, existsSync } = await import('node:fs');
if (!globalThis.input.note_path) { throw new Error('note_path missing'); }
if (!existsSync(globalThis.input.note_path)) { throw new Error('note file not found'); }
globalThis.noteBuffer = readFileSync(globalThis.input.note_path);
if (globalThis.input.font_path) {
  if (!existsSync(globalThis.input.font_path)) { throw new Error('font file not found'); }
  globalThis.fontBytes = readFileSync(globalThis.input.font_path);
}

const mod = await import('supernote-typescript');
const { SupernoteX, toPdf } = mod;
const note = new SupernoteX(globalThis.noteBuffer);
let options = {};
if (globalThis.fontBytes) { options.fontBytes = globalThis.fontBytes; }
try {
  const pdfBytes = await toPdf(note, options);
  globalThis.pdfBytes = pdfBytes;
} catch (e) {
  globalThis.pdfBytes = Buffer.alloc(0);
}

const { Buffer } = await import('node:buffer');
const out = { pdf_base64: Buffer.from(globalThis.pdfBytes).toString('base64') };
console.log(JSON.stringify(out));
